setInterval(checkForUpdates,15000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkForUpdates(true);});
window.addEventListener('focus',()=>checkForUpdates(true));
modal.addEventListener('close',()=>{if(stale&&currentUser)checkForUpdates(true);});
reportDialog.addEventListener('close',()=>{if(stale&&currentUser)checkForUpdates(true);});

function requestPaymentsButton(){const list=filteredRows().filter(r=>r.closed&&!r.paid&&!r.requestId&&r.net>0);return `<button class="btn primary" data-action="request-payments" ${!list.length||!canOperate()?'disabled':''}>Enviar para pagamento</button>`;}
function portalClosingNotice(list){const count=list.filter(r=>r.requestId&&!r.paid).length;return `<div class="notice neutral"><span>${count?count+' placa(s) jÃ¡ solicitada(s) Ã  transportadora.':'Depois do fechamento, solicite os pagamentos Ã  transportadora. O grupo acompanha os comprovantes pelo portal.'}</span><a href="#requests">Acompanhar solicitaÃ§Ãµes â†’</a></div>`;}
function paymentDetailsMarkup(input,status='pending'){
 const missing=paymentDetailsMissing(input);
 if(missing.length)return `<div class="form-note warn"><strong>Dados de pagamento nÃ£o registrados nesta solicitaÃ§Ã£o.</strong>${status==='pending'?'<br>O grupo precisa cancelar a solicitaÃ§Ã£o, preencher o cadastro da placa e enviar novamente.':''}</div>`;
 const details=normalizePaymentDetails(input);
 const destination=details.method==='pix'?`Chave Pix: <strong>${e(details.pixKey)}</strong>`:`Banco: <strong>${e(details.bankName)}</strong><br>AgÃªncia: <strong>${e(details.agency)}</strong> Â· Conta: <strong>${e(details.account)}</strong> Â· Tipo: <strong>${e({corrente:'Corrente',poupanca:'PoupanÃ§a',pagamento:'Pagamento'}[details.accountType])}</strong>`;
 return `<div class="form-note"><strong>Dados para pagamento</strong><br>${e(PAYMENT_METHODS[details.method])} Â· Titular: <strong>${e(details.holder)}</strong><br>CPF/CNPJ: <strong>${e(formatPaymentDocument(details.document))}</strong><br>${destination}</div>`;
}
