 if(isCarrier()||!canOperate())throw Error('A solicitaÃ§Ã£o exige acesso do grupo.');const list=filteredRows().filter(r=>r.closed&&!r.paid&&!r.requestId&&r.net>0&&(!truckId||r.truckId===truckId));if(!list.length)throw Error('NÃ£o hÃ¡ placas fechadas e sem solicitaÃ§Ã£o nesta seleÃ§Ã£o.');
